class Solution {
    public TreeNode insertBST(TreeNode root, int x) {
        if (root == null) {
            return new TreeNode(x);
        }
        if (x < root.val) {
            root.right = insertBST(root.right, x);
        } else if (x > root.val) {
            root.left = insertBST(root.left, x);
        }
        return root;
    }
}
